        if (feliz > chateado) {
            System.out.println("divertido");
        } else if (chateado > feliz) {
            System.out.println("chateado");
        } else {
            System.out.println("neutro");
        }
    }

    static int contar(String s, String padrao) {
        int c = 0;
        int idx = 0;
